import{_ as t,o as i,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Sequence Flow — Invite Agency Member → Accept Invitation","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-7-invite-agency-member/sequence-flow.md","filePath":"feature/agency-workspace/3-4-7-invite-agency-member/sequence-flow.md"}'),a={name:"feature/agency-workspace/3-4-7-invite-agency-member/sequence-flow.md"};function s(r,e,d,l,h,c){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-invite-agency-member-→-accept-invitation" tabindex="-1">Sequence Flow — Invite Agency Member → Accept Invitation <a class="header-anchor" href="#sequence-flow-—-invite-agency-member-→-accept-invitation" aria-label="Permalink to &quot;Sequence Flow — Invite Agency Member → Accept Invitation&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.7) and to <code>3-4-8-view-agency-invitation-status/spec.md</code> (FR 3.4.8). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Owner</strong> — owns the Agency and sends the invitation.</li><li><strong>Invitee</strong> — the person invited; may not have an account yet.</li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agency_invitations</code>, <code>agency_members</code>, <code>workspace_members</code>, <code>client_profiles</code>).</li><li><strong>Mail</strong> — the outgoing email service; the invitation email is sent without holding up the answer to the client.</li></ul><hr><h2 id="flow-a-—-the-owner-sends-an-invitation-role-manager-or-creator-not-client" tabindex="-1">Flow A — The Owner sends an invitation (role MANAGER or CREATOR, not CLIENT) <a class="header-anchor" href="#flow-a-—-the-owner-sends-an-invitation-role-manager-or-creator-not-client" aria-label="Permalink to &quot;Flow A — The Owner sends an invitation (role MANAGER or CREATOR, not CLIENT)&quot;">​</a></h2><ol><li>Owner → Client: opens the Member list of the Agency and fills in the form (email, optional invitee name, optional note, expiry between 1 and 30 days defaulting to 30, optional Workspace and role).</li><li>Client → System: submits the invitation (<code>POST /api/v1/agencies/{agencyId}/invitations</code>) with email, invitee name, note, Workspace, role and expiry period.</li><li>System — check and store: a. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. b. Confirms the email is not already a Member of the Agency — otherwise <code>409 ALREADY_AGENCY_MEMBER</code>. c. Confirms the email holds no unexpired PENDING invitation for this Agency — otherwise <code>409 INVITATION_ALREADY_PENDING</code>. d. Confirms the Agency holds fewer than 20 PENDING invitations — otherwise <code>409 TOO_MANY_PENDING_INVITATIONS</code>. e. When a Workspace is sent: confirms it belongs to the same Agency — otherwise <code>400 WORKSPACE_NOT_IN_AGENCY</code>. With the role MANAGER, confirms the Workspace holds no active manager — otherwise <code>409 MANAGER_ALREADY_ASSIGNED</code>. With the role CLIENT, confirms a Workspace was sent — otherwise <code>400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code> (see Flow B). f. Stores the invitation as PENDING, with a random token, an expiry time computed from the expiry period, the note, the Workspace and the role. <ul><li>At the Database level, the PENDING uniqueness is partial: it applies to rows in the PENDING status only, so an email whose earlier invitation was withdrawn or has lapsed can be invited again.</li></ul></li><li>System → Mail: sends the invitation email, carrying an accept link with the token, without holding up the answer to the client.</li><li>System → Client: the stored invitation (identifier, Agency, invited email, sender, token, note, Workspace, role, status PENDING, expiry time, no acceptance time, creation time).</li><li>Client: shows a confirmation and adds the row to the PENDING invitation table.</li></ol><h2 id="flow-b-—-the-owner-sends-an-invitation-with-the-role-client" tabindex="-1">Flow B — The Owner sends an invitation with the role CLIENT <a class="header-anchor" href="#flow-b-—-the-owner-sends-an-invitation-with-the-role-client" aria-label="Permalink to &quot;Flow B — The Owner sends an invitation with the role CLIENT&quot;">​</a></h2><p>Same as Flow A steps 1–3, with two differences:</p><ul><li>A Workspace is mandatory from step 1; the Client blocks submission when the role CLIENT is selected without a Workspace.</li><li>The System stores the role CLIENT together with the Workspace on the invitation, and creates no Workspace membership at this point — that happens only on acceptance (see Flow D).</li></ul><hr><h2 id="flow-c-—-the-invitee-already-has-an-account-and-opens-the-invitation-link" tabindex="-1">Flow C — The Invitee already has an account and opens the invitation link <a class="header-anchor" href="#flow-c-—-the-invitee-already-has-an-account-and-opens-the-invitation-link" aria-label="Permalink to &quot;Flow C — The Invitee already has an account and opens the invitation link&quot;">​</a></h2><ol><li>Invitee → Client: opens the accept link from the email, landing on the invitation screen with the token.</li><li>Client: sees the Invitee is already signed in and lets them through, with no redirect.</li><li>Client → System: accepts the invitation with the token (<code>POST /api/v1/agencies/invitations/accept</code>).</li><li>System — accept: a. Finds the invitation by token — not found → <code>400 INVALID_INVITATION</code>. b. Confirms it is PENDING and not past its expiry time — otherwise <code>400 INVALID_INVITATION</code>. c. Confirms the invited email matches the email of the signed-in user — otherwise <code>400 INVALID_INVITATION</code>. d. When the role is CLIENT, branches to <strong>Flow D</strong> and returns early. e. Confirms the person is not already a Member of the Agency — otherwise <code>409 ALREADY_AGENCY_MEMBER</code>. f. Stores a member record for the Agency at the MEMBER role. The Agency level knows OWNER and MEMBER only; any finer role lives at the Workspace level. g. Marks the invitation ACCEPTED with the acceptance time.</li><li>System → Client: the new membership (Agency, person, name, email and the like).</li><li>Client: shows a confirmation and, after a short pause, takes the person back to the Agency landing area.</li></ol><h2 id="flow-d-—-accepting-an-invitation-with-the-role-client" tabindex="-1">Flow D — Accepting an invitation with the role CLIENT <a class="header-anchor" href="#flow-d-—-accepting-an-invitation-with-the-role-client" aria-label="Permalink to &quot;Flow D — Accepting an invitation with the role CLIENT&quot;">​</a></h2><p>Continues from Flow C step 4.d:</p><ol><li>System: confirms the invitation carries a Workspace. Without one — corrupted data that Flow B prevents — it refuses with <code>400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code>.</li><li>System → Database: looks up the Client Profile for this person and Agency and creates it when missing.</li><li>System → Database: confirms the person holds no active Workspace membership in that Workspace, and creates one when missing, at the CLIENT role, linked to the Client Profile and recorded as added by the sender of the invitation. <ul><li>At the Database level, the membership identity rule requires a Client Profile for a CLIENT membership, and a person identifier for every other role. A CLIENT membership carries both the person and the Client Profile, so a client can sign in themselves.</li></ul></li><li>System: marks the invitation ACCEPTED with the acceptance time.</li><li>System → Client: the new membership, using the same shape as the non-CLIENT branch.</li><li>Client: behaves as in Flow C step 6.</li></ol><hr><h2 id="flow-e-—-the-invitee-has-no-account-yet-and-opens-the-invitation-link" tabindex="-1">Flow E — The Invitee has no account yet and opens the invitation link <a class="header-anchor" href="#flow-e-—-the-invitee-has-no-account-yet-and-opens-the-invitation-link" aria-label="Permalink to &quot;Flow E — The Invitee has no account yet and opens the invitation link&quot;">​</a></h2><p>This is the branch corrected on 2026-09-23: the invitation destination used to be lost somewhere between registration, verification and sign-in.</p><ol><li>Invitee → Client: opens the accept link from the email, landing on the invitation screen with the token.</li><li>Client: sees the Invitee is not signed in and redirects to the sign-in screen, keeping the invitation destination (screen and token) as the place to come back to.</li><li>Client: records that destination before the Invitee leaves the sign-in screen.</li><li>Invitee switches to Register — the Client keeps the recorded destination; nothing has to be carried across by hand.</li><li>Client: the registration screen also records the destination when it arrives there directly, for the case where the redirect lands there in one step.</li><li>Invitee submits the registration form → Client → System: registers the account. The System creates the person as not yet active and sends a verification code by email.</li><li>Client: moves to the verification screen. The recorded destination stays in place, untouched by this step.</li><li>Invitee enters the code → Client → System: verifies it. On success the Client moves to the sign-in screen.</li><li>Invitee signs in → Client → System: signs in. <ul><li><strong>Sub-branch — the account has two-factor authentication enabled:</strong> the System answers with a two-factor challenge, and the Client takes the Invitee through the verification screen before the sign-in completes. The recorded destination is untouched by this detour, because it stays within the same tab of the Client.</li></ul></li><li>On success the Client stores the session, loads the person&#39;s own profile, and returns to the recorded destination — the invitation screen with the token, recorded back at step 3. When nothing was recorded, it falls back to the general landing screen.</li><li>The Client resumes <strong>Flow C from step 3</strong>: the Invitee is now signed in, so the invitation is accepted with the token.</li></ol><h3 id="sub-branch-—-signing-in-with-google-with-no-account-yet" tabindex="-1">Sub-branch — signing in with Google, with no account yet <a class="header-anchor" href="#sub-branch-—-signing-in-with-google-with-no-account-yet" aria-label="Permalink to &quot;Sub-branch — signing in with Google, with no account yet&quot;">​</a></h3><p>Steps 6 to 10 are replaced by:</p><p>6&#39;. Invitee selects the Google option on the sign-in screen. The link leaves the application entirely and the browser goes to the sign-in provider.</p><ul><li>The recorded destination was stored at step 3, before leaving the screen, and survives the trip outside the application because it belongs to the browser tab. 7&#39;. System: handles the sign-in with the provider and returns to the Client.</li><li><strong>Sub-branch — the account has two-factor authentication enabled:</strong> the System sends the Client to the two-factor screen with its challenge in the address, instead of step 8&#39;. The Client reads the challenge from the address first and falls back to the stored one. After verification it continues to step 10&#39;, with the recorded destination still in place from step 6&#39;.</li><li>Without two-factor authentication: the System sends the Client straight to the callback screen with the session token in the address fragment. 8&#39;. Client: reads the session token from the address, loads the person&#39;s own profile and stores the session. 9&#39;. Client: returns to the recorded destination, the invitation screen with the token. 10&#39;. The Client resumes <strong>Flow C from step 3</strong>.</li></ul><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Invite (Flow A/B)</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Invite</td><td>Email is already a Member of the Agency</td><td>409</td><td><code>ALREADY_AGENCY_MEMBER</code></td></tr><tr><td>Invite</td><td>Email already holds a PENDING invitation</td><td>409</td><td><code>INVITATION_ALREADY_PENDING</code></td></tr><tr><td>Invite</td><td>The Agency already holds 20 PENDING invitations</td><td>409</td><td><code>TOO_MANY_PENDING_INVITATIONS</code></td></tr><tr><td>Invite</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>Invite</td><td>Workspace does not belong to this Agency</td><td>400</td><td><code>WORKSPACE_NOT_IN_AGENCY</code></td></tr><tr><td>Invite</td><td>Role MANAGER but the Workspace already has an active manager</td><td>409</td><td><code>MANAGER_ALREADY_ASSIGNED</code></td></tr><tr><td>Invite</td><td>Role CLIENT without a Workspace</td><td>400</td><td><code>WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code></td></tr><tr><td>Accept</td><td>The token does not exist</td><td>400</td><td><code>INVALID_INVITATION</code></td></tr><tr><td>Accept</td><td>The invitation is not PENDING or has passed its expiry time</td><td>400</td><td><code>INVALID_INVITATION</code></td></tr><tr><td>Accept</td><td>The signed-in email differs from the invited email</td><td>400</td><td><code>INVALID_INVITATION</code></td></tr><tr><td>Accept (non-CLIENT)</td><td>The person is already a Member of the Agency</td><td>409</td><td><code>ALREADY_AGENCY_MEMBER</code></td></tr><tr><td>Accept (CLIENT)</td><td>The invitation carries no Workspace</td><td>400</td><td><code>WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Correction applied:</strong> an earlier revision of <code>spec.md</code> (3.4.7) stated that registering with the invited email address accepts the invitation automatically. That is wrong for the system as built. There is no automatic acceptance: the invitation is accepted only when the link is opened or the token is submitted after the account exists (Flow E step 11).</li><li><strong>Correction applied:</strong> an earlier revision recorded an in-app notification alongside the email. Only the email is sent; the system has no shared notification module yet.</li><li><strong>Correction applied:</strong> an earlier revision recorded the invitation as returning a created-resource answer. The answer is a plain success (HTTP 200), not a created-resource answer.</li><li><strong>Correction applied:</strong> an earlier revision recorded a fixed 3-day expiry. The expiry now defaults to 30 days and is settable between 1 and 30 days.</li><li><strong>Correction applied:</strong> an earlier revision listed a direct Workspace-and-role invitation as out of scope. It is in place: the invitation carries a Workspace and a role, and the matching Workspace membership is added on acceptance.</li></ul>',29)])])}const g=t(a,[["render",s]]);export{m as __pageData,g as default};
